INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','7ff30dc0-15b7-4e11-b641-e3eadd6a37d8',NULL,2022,10,12,'War & Conflict',65,'{"id":"7ff30dc0-15b7-4e11-b641-e3eadd6a37d8","ad_day":12,"ad_date":null,"ad_year":2022,"bs_date":null,"country":null,"sources":[],"ad_month":10,"category":"War & Conflict","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"2022 Bratislava shooting, killing 3 (including the perpetrator) and injuring one. The shooting occured outside of a gay bar in Bratislava known as Tepláreň. Two people (excluding the perpetrator) died as a result of the shooting. Juraj Vankulič, a non-binary person, and Matúš Horváth, a bisexual man. The perpetrator (Juraj Krajčík) was found dead due to a self inflicted gunshot the morning after the attack.","title_ne":"२०२२ ब्रातिस्लाभामा गोलीबारी, ३ जनाको मृत्यु (अपराधी सहित) र एक जना घाइते। ब्रातिस्लाभामा टेप्लारेन भनेर चिनिने समलिङ्गी बार बाहिर गोलीबारी भएको थियो। गोलीबारीका कारण दुई जनाको मृत्यु भयो (अपराधी बाहेक)। जुराज भान्कुलिक, एक गैर-द्वयसांख्यिक व्यक्ति, र मातुस होर्भाथ, एक उभयलिंगी पुरुष। आक्रमणको भोलिपल्ट बिहान आत्मघाती गोली लागेर अपराधी (जुराज क्राजिक) मृत फेला परेका थिए।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:40.152741+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/2022_Bratislava_shooting","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:40.152741+00:00","source_name":"User-provided historical dataset","country_code":null,"image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=2022%20Bratislava%20shooting&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"2022 Bratislava shooting","source_record_id":"1012-2022-e-vc25z2","verification_status":"source-backed","event_date_precision":"day"}','2026-09-19T03:30:40.152741+00:00');
